import { Schema as S } from "effect";
import type { Command } from "foldkit";
import { Submodel } from "foldkit";
import type { Html } from "foldkit/html";

import * as Alert from "../../ui/alert";

// MODEL

export const Model = S.Struct({});
export type Model = typeof Model.Type;

// MESSAGE

export const Message = S.Never;
export type Message = typeof Message.Type;

// INIT

export const init = (): readonly [
  Model,
  readonly Command.Command<Message>[],
] => [{}, []];

// UPDATE

export const update = (
  model: Model,
  _message: Message
): readonly [Model, readonly Command.Command<Message>[]] => [model, []];

// VIEW

export const view = Submodel.defineView<Model, Message>(
  (): Html =>
    Alert.view<Message>({
      title: "Your subscription will expire in 3 days.",
      description:
        "Renew now to avoid service interruption or upgrade to a paid plan to continue using the service.",
      icon: "!",
      variant: "Default",
      classes: Alert.alertCustomColorClasses,
    })
);

import { Runtime } from "foldkit";

import { Model, init, update, view } from "./main";

const program = Runtime.makeProgram({
  Model,
  init,
  update,
  view: (model) => ({
    title: "Alert Custom Colors",
    body: view(model),
  }),
  container: document.querySelector("#root"),
});

Runtime.run(program);

import { Scene } from "foldkit";
import { describe, test } from "vitest";

import { init, update, view } from "./main";

describe("alert-custom-colors example", () => {
  test("renders the shadcn custom colors alert copy", () => {
    const [model] = init();

    Scene.scene(
      { update, view },
      Scene.with(model),
      Scene.expect(Scene.role("alert")).toExist(),
      Scene.expect(Scene.role("alert")).toHaveClass("bg-amber-50"),
      Scene.expect(
        Scene.role("heading", {
          name: "Your subscription will expire in 3 days.",
        })
      ).toExist(),
      Scene.expect(
        Scene.text(
          "Renew now to avoid service interruption or upgrade to a paid plan to continue using the service."
        )
      ).toExist(),
      Scene.expect(
        Scene.text("Your subscription will expire in 3 days.")
      ).not.toHaveHandler("click")
    );
  });
});
